import re
src = open('/tmp/dsh-spill-SP27Td/session-783de0790d52/59a601109340-web_fetch_pro.txt').read()
print(len(src))
# find the export mapping at top: import{...F as Ko...} from Global. Find 'as Ko' etc in the import list — but that's in this file's header.
# The actual definitions of Ko, Dd are inside Global bundle. Let's search for function patterns with 2 string args like (n,i) that build URLs:
for pat in [r'[A-Za-z0-9_$]{1,4}=\(?[a-z],[a-z](?:,[a-z])*\)?=>[^;]{0,300}', r'function [A-Za-z0-9_$]{1,4}\([a-z],[a-z](?:,[a-z])*\)\{[^}]{0,300}']:
    for m in re.finditer(pat, src):
        s = m.group(0)
        if 'fetch' in s or 'ajax' in s or 'url' in s.lower() or 'concat' in s:
            print(s[:400])
            print('---')
EOF","description":"Search app JS for URL-building function definitions"}

